import{_ as o,o as r,c as e,a2 as a}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"MCP 接続","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/mcp.md","filePath":"ja/guides/mcp.md","lastUpdated":1792323081000}'),n={name:"ja/guides/mcp.md"};function d(s,t,h,i,l,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="mcp-接続" tabindex="-1">MCP 接続 <a class="header-anchor" href="#mcp-接続" aria-label="Permalink to &quot;MCP 接続&quot;">​</a></h1><p>Memoh は <strong>Model Context Protocol (MCP)</strong> をサポートしており、Bot を外部ツールやコンテキストサービスに接続できます。各 Bot は自分専用の MCP 接続のセットを持てます。</p><h2 id="何をするものか" tabindex="-1">何をするものか <a class="header-anchor" href="#何をするものか" aria-label="Permalink to &quot;何をするものか&quot;">​</a></h2><p>MCP は「外部データ・外部ツール」を比較的統一された方法で取り込みます。Bot の <strong>MCP</strong> タブで手動設定するか、<a href="./supermarket.html">マーケットプレイス</a> からテンプレートをインストールしてエディターで調整します。</p><hr><h2 id="接続タイプ" tabindex="-1">接続タイプ <a class="header-anchor" href="#接続タイプ" aria-label="Permalink to &quot;接続タイプ&quot;">​</a></h2><h3 id="_1-stdio-ローカルプロセス" tabindex="-1">1. Stdio（ローカルプロセス） <a class="header-anchor" href="#_1-stdio-ローカルプロセス" aria-label="Permalink to &quot;1. Stdio（ローカルプロセス）&quot;">​</a></h3><p>Bot の<strong>コンテナ内</strong>でローカルコマンドを起動し、標準入出力で通信します。</p><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th></tr></thead><tbody><tr><td><strong>Command</strong></td><td>実行ファイル。例: <code>npx</code>、<code>python3</code></td></tr><tr><td><strong>Arguments</strong></td><td>引数のリスト</td></tr><tr><td><strong>Env</strong></td><td>環境変数</td></tr><tr><td><strong>CWD</strong></td><td>作業ディレクトリ</td></tr></tbody></table><h3 id="_2-remote-http-sse" tabindex="-1">2. Remote（HTTP/SSE） <a class="header-anchor" href="#_2-remote-http-sse" aria-label="Permalink to &quot;2. Remote（HTTP/SSE）&quot;">​</a></h3><p>ネットワーク経由のリモート MCP です。</p><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th></tr></thead><tbody><tr><td><strong>URL</strong></td><td>サーバーのエンドポイント</td></tr><tr><td><strong>Headers</strong></td><td>認証ヘッダーなど</td></tr><tr><td><strong>Transport</strong></td><td><code>http</code> または <code>sse</code></td></tr></tbody></table><hr><h2 id="oauth" tabindex="-1">OAuth <a class="header-anchor" href="#oauth" aria-label="Permalink to &quot;OAuth&quot;">​</a></h2><p>OAuth が必要な MCP サーバーもあります。Memoh は MCP の OAuth フローを完全にサポートしています。</p><ol><li>認証が必要な接続で <strong>OAuth</strong> をクリックします。</li><li>サーバー側の OAuth 設定を自動で <strong>discover</strong> します。</li><li><strong>Authorize</strong> で認可ページを開きます。</li><li>ユーザーが同意するとリダイレクトで戻り、Memoh が <strong>token を交換</strong>して安全に保存します。</li></ol><p>状態の確認や、<strong>Revoke</strong> による token の削除もできます。</p><hr><h2 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to &quot;操作&quot;">​</a></h2><ul><li><strong>Add Connection</strong>：接続を 1 件追加します。タイプを選んでフォームに入力します。</li><li><strong>Import JSON</strong>：標準の <code>mcpServers</code> JSON から複数の接続を一括インポートします。</li><li><strong>Export</strong>：バックアップや共有のためにエクスポートします。</li><li><strong>Toggle Active</strong>：削除せずに、個別の接続をオン／オフします。</li><li><strong>Search</strong>：名前または id で探します。</li><li><strong>Batch Delete</strong>：複数選択して削除します。</li></ul><hr><h2 id="ツール検出" tabindex="-1">ツール検出 <a class="header-anchor" href="#ツール検出" aria-label="Permalink to &quot;ツール検出&quot;">​</a></h2><p>接続が active になると、Memoh はそのサーバーが公開するツールを取得します。接続を開くと <strong>Tools</strong> の一覧を確認できます。必要に応じて <strong>Probe</strong> で手動更新します。</p><hr><h2 id="bot-との連携" tabindex="-1">Bot との連携 <a class="header-anchor" href="#bot-との連携" aria-label="Permalink to &quot;Bot との連携&quot;">​</a></h2><p>接続が確立すると、会話の中でモデルが説明に従ってこれらのツールを選んで使います。検出されたツールは推論フローに組み込まれます。具体的なツール名やパラメーターはサーバー側の定義に従います。</p>',26)])])}const m=o(n,[["render",d]]);export{p as __pageData,m as default};
